    rx('потер\\W*\\s*сознани|(упал|потерял\\W*|отключил\\W*)[^.!?]{0,20}(в\\s*обморок|сознание|отруб)|(перв\\W*\\s*раз|впервые)[^.!?]{0,20}судорог|судорог\\W*[^.!?]{0,25}(не\\s*прекращ|вс[её]\\s*тело|минут)|эпи?приступ|припадок\\s*(с|со|без)\\s*судорог')],
  ['внезапная нестерпимая боль в животе/боку/спине',
    rx('(внезапн\\W*|резк\\W*|остр\\W*)[^.!?]{0,15}(сильнейш\\W*|нестерпим\\W*|острейш\\W*|кинжальн\\W*|невыносим\\W*)[^.!?]{0,20}бол\\W*[^.!?]{0,20}(живот|поясниц|спин|бок|подреберь)|бол\\W*[^.!?]{0,12}(как\\s*удар\\s*ножом|будто\\s*разрыв)')],
  ['задержка мочи',
    rx('(не\\s*могу\\s*(по)?мочит\\W*|не\\s*могу\\s*сходить\\s*по-?маленьк\\W*|моча\\s*не\\s*идет|не\\s*идет\\s*моча|мочев\\W*\\s*переполн|переполнен\\s*мочев|распира\\W*\\s*внизу\\s*живот|не\\s*могу\\s*опорожнить\\s*мочев)[^.!?]{0,55}(боль|распира|переполн|полдня|сутки|давно|много\\s*часов|тужусь|не\\s*получается)')],
  ['острая закрытоугольная глаукома / внезапная потеря зрения на один глаз',
    rx('(резк\\W*|сильн\\W*|остр\\W*)[^.!?]{0,15}бол\\W*[^.!?]{0,15}(в\\s*глаз|глаза)[^.!?]{0,70}(радужн\\W*\\s*круг|ореол\\W*\\s*вокруг\\s*свет|круги\\s*вокруг\\s*ламп|затуман\\W*\\s*зрени|глаз\\s*(красн|твердый|каменн|как\\s*камень)|тошнот|рвот|половин\\W*\\s*голов)|(внезапн\\W*|резк\\W*|за\\s*час|за\\s*(несколько\\s*)?минут)[^.!?]{0,20}(упало|пропало|исчезло|потемнело|потерял\\W*)\\s*зрени[^.!?]{0,25}(на\\s*один\\s*глаз|в\\s*одном\\s*глаз|левым\\s*глаз|правым\\s*глаз|один\\s*глаз)')],
  ['лихорадка + спутанность / ригидность шеи',
    rx('(температур\\W*|жар|лихорадк)[^.!?]{0,20}(3[89]|4[012])[^.!?]{0,55}(спутан|брежу|бред\\b|не\\s*могу\\s*согнуть\\s*шею|ригидн|светобоязн|сыпь\\s*не\\s*исчез)|не\\s*могу\\s*согнуть\\s*шею[^.!?]{0,25}(температур|жар|свет|голов)')],
];

const redFlag = { hit: false, matched: [], category: 'emergency' };
for (const [label, re] of RED_FLAGS) {
  if (re.test(msg)) { redFlag.hit = true; redFlag.matched.push(label); }
}
if (redFlag.hit && redFlag.matched.length === 1 && /суицидальные/.test(redFlag.matched[0])) {
  redFlag.category = 'crisis';
} else if (redFlag.matched.some(x => /суицидальные/.test(x))) {
  // суицид + что-то ещё → всё равно ведём как emergency, но пометим
  redFlag.category = 'emergency';
}

// ======================= МЯГКАЯ СЕТЬ (не короткое замыкание) =======================
// Односложная зацепка → агент ОБЯЗАН уточнить перечисленное прежде чем строить гипотезы.
const SOFT = [
  [rx('(боль[^.!?]{0,12}в\\s*груди|груд\\W*\\s*болит|болит[^.!?]{0,12}груд|за\\s*грудин|колет\\s*в\\s*сердц|давит\\s*в\\s*груди)'),
   'Боль/дискомфорт в груди: иррадиация (рука/челюсть/лопатка/спина/эпигастрий), одышка, холодный пот, тошнота, связь с физнагрузкой, длительность эпизода, было ли такое раньше и что снимало.'],
  [rx('(головн\\W*\\s*боль|болит\\s*голова|голова\\s*болит|мигрен)'),
   'Головная боль: внезапная («секунды-минуты, как удар») или постепенная; самая сильная в жизни?; температура, ригидность шеи, свето/звукобоязнь, сыпь; онемение/слабость/нарушение речи/двоение; травма головы в последние дни.'],
  [rx('(онемел|онемени\\W*|неме\\W*т|отня\\W*|отнимает|покалыван|мурашк|ватн\\W*\\s*ног)'),
   'Онемение/слабость: одна сторона или обе; лицо, речь, рука (инсульт); промежность/седловидная зона + контроль мочеиспускания и стула (конский хвост — критично при грыже L5/S1); нарастает или стабильно; с какого момента.'],
  [rx('(кровь|кров\\W*\\s*т|кровот\\W*|окровав|кровит)'),
   'Кровь: точный источник (рвота / стул / моча / мокрота / нос / дёсны / рана); цвет (алая / тёмная / «кофейная гуща» / чёрный дёгтеобразный); объём; однократно или повторяется; принимает ли антикоагулянты/НПВС.'],
  [rx('(температур|жар\\b|лихорад|озноб|знобит)'),
   'Лихорадка: точная цифра и сколько дней; ригидность затылка, спутанность, сыпь которая не бледнеет при надавливании; одышка; локальная боль (живот/бок/горло/ухо/мочеиспускание); поездки, укусы клещей.'],
  [rx('(задыха\\W*|одышк|не\\s*хватает\\s*воздух|тяжело\\s*дышать|трудно\\s*дышать|нехватк\\W*\\s*воздух)'),
   'Одышка: в покое или при нагрузке; появилась внезапно или постепенно; боль в груди при вдохе; отёк или боль в одной ноге (ТГВ); кашель, кровь в мокроте; тяжело дышать лёжа (ортопноэ); отёки ног к вечеру.'],
  [rx('(сильно\\s*похуд|похудел\\W*\\s*без\\s*причин|теряю\\s*вес|резко\\s*похуд|сброс\\W*\\s*вес\\W*\\s*без)'),
   'Потеря веса: сколько кг за какой срок; аппетит; ночная потливость; субфебрилитет; изменения стула/глотания; когда последний раз проходил онко-скрининги по возрасту.'],
  [rx('(родинк|невус|пятно\\s*на\\s*коже|нарост|новообразован|уплотнени\\W*\\s*в\\s*(груд|молочн)|шишк\\W*\\s*(под\\s*кож|в\\s*груд|на\\s*шее))'),
   'Кожное/подкожное образование: как давно; менялось ли (размер, цвет, форма, неровные края, зуд, кровоточивость, изъязвление) — правило ABCDE; для уплотнения в груди — связь с циклом, выделения, втяжение кожи/соска.'],
  [rx('(кружит\\W*\\s*голов|головокружени|шатает\\s*при\\s*ходьбе|теряю\\s*равновеси|пошатыва)'),
   'Головокружение: ощущение вращения или «дурноты/пустоты в голове»; двоение, нарушение речи, онемение, асимметрия лица, резкая шаткость (центральные признаки); связь с положением тела; шум или снижение слуха в одном ухе; приём новых препаратов.'],
  [rx('(сердцебиени|колотит\\W*\\s*сердц|пропуск\\W*\\s*в\\s*сердц|перебо\\W*\\s*в\\s*сердц|аритми|трепыхает\\s*сердц)'),
   'Сердцебиение: ритмичное или с перебоями/паузами; сопровождается обмороком, предобмороком, болью в груди, одышкой; сколько длится и как заканчивается; провокаторы (кофе, алкоголь, стресс, нагрузка, недосып).'],
  [rx('(запор\\W*\\s*(нескольк|недел|давно)|не\\s*могу\\s*сходить\\s*в\\s*туалет\\s*по-?больш|кал\\s*тонк\\W*\\s*как\\s*лент|изменил\\W*\\s*форм\\W*\\s*стул)'),
   'Изменение стула: как давно; кровь или слизь; форма (тонкий как лента); чередование запор/понос; ночные позывы; потеря веса; семейный анамнез по колоректальному раку; когда была колоноскопия.'],
  [rx('(хочу\\s*умереть|хочу\\s*сдохнуть|устал\\s*(от\\s*всего|жить)|всё\\s*надоело|нет\\s*сил\\s*(больше\\s*)?(жить|терпеть|это\\s*терпеть)|опустились\\s*руки|беспросвет|ничего\\s*не\\s*радует|жить\\s*не\\s*хочется)'),
   'Настроение и безопасность: аккуратно и без осуждения уточни — есть ли мысли о том, чтобы не жить / причинить себе вред; как давно подавленность, сон, аппетит, ангедония; если есть суицидальные мысли или план — это неотложно, дай контакт кризисной линии (телефон доверия 8-800-2000-122, круглосуточно) и настойчиво предложи связаться со специалистом.'],
];
const soft_flags = [];
for (const [re, ask] of SOFT) {
  if (re.test(msg)) soft_flags.push(ask);
}
// не дублируем мягкое, если ровно та же тема уже поймана жёстким флагом
const soft_probe = (!redFlag.hit && soft_flags.length)
  ? ('## ❗ ОБЯЗАТЕЛЬНО УТОЧНИ (автоподсказка по ключевым словам сообщения — это НЕ признак неотложки):\n- '
      + soft_flags.join('\n- ')
      + '\nПока не уточнишь перечисленное по этому пункту — не формулируй гипотезы и не закрывай жалобу. Задай 1–2 самых важных вопроса и жди ответа.')
  : '';

// ---------- картотека препаратов (лист Meds) — для проверки взаимодействий ----------
const medsRows = (() => { try { return $('Get Meds').all().map(i => i.json); } catch (e) { return []; } })();
function d10med(v) { const s = String(v == null ? '' : v).trim().slice(0, 10); return /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : null; }
const medsCard = medsRows
  .filter(x => x && (x.Name || x.Med_ID) && String(x.Med_ID || '').toLowerCase() !== 'demo-format')
  .map(x => ({
    name: String(x.Name || x.Med_ID).trim(),
    class: String(x.Class || '').trim() || null,
    dose: String(x.Dose || '').trim() || null,
    status: String(x.Status || '').trim().toLowerCase() || 'unknown',
    started: d10med(x.Started),
    stopped: d10med(x.Stopped),
    reason: String(x.Reason || '').trim() || null,
  }));
const nowMs = Date.now() + 10 * 3600 * 1000;
const _active = medsCard.filter(x => ['active', 'prn', 'paused'].includes(x.status));
const _stoppedRecent = medsCard
  .filter(x => x.status === 'stopped' && x.stopped && (nowMs - new Date(x.stopped).getTime()) / 86400000 <= 120)
  .sort((a, b) => String(b.stopped).localeCompare(String(a.stopped)));
const _fmt = x => x.name + (x.dose ? ' ' + x.dose : '') + (x.reason ? ' — ' + x.reason : '');
const medications = {
  active: _active,
  stopped_recent: _stoppedRecent,
  // компактная строка для промпта — без JSON-дампа, чтобы не грузить reasoning модели
  summary: 'Сейчас: ' + (_active.length ? _active.map(_fmt).join('; ') : 'по картотеке ничего')
    + '. Недавно закончены курсы: ' + (_stoppedRecent.length
      ? _stoppedRecent.map(x => x.name + ' (до ' + x.stopped + (x.reason ? ', ' + x.reason : '') + ')').join('; ')
      : 'нет') + '.',
};

const result = {
  json: {
    medical_record: sheetData,
    user_message: msg,
    telegram_id: m.from && m.from.id,
    chat_id: m.chat && m.chat.id,
    red_flag: redFlag,
    soft_flags,
    soft_probe,
    medications,
    input_kind: rawText ? (isForwarded ? 'forwarded' : 'text')
      : (m.voice || m.audio || m.video_note) ? 'voice'
      : m.photo ? 'photo_no_caption'
      : m.document ? 'document' : 'unknown',
    today: new Date(Date.now() + 10 * 3600 * 1000).toISOString().slice(0, 10),
  },
};
if (binaryData) result.binary = binaryData;
return [result];

let text = $json.output || "";

// 1. Превращаем <br> и <p> в нормальные текстовые переносы
text = text.replace(/<br\s*\/?>/gi, '\n');
text = text.replace(/<\/?p>/gi, '\n\n');

// 2. Спасаем жирный шрифт (Markdown в HTML)
text = text.replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');
text = text.replace(/\*/g, '');

// 3. СПАСАЕМ МЕДИЦИНСКИЕ АНАЛИЗЫ (знаки < и >)
// Если после < идет пробел или цифра - это точно математика, а не тег
text = text.replace(/<(?=\s|[0-9])/g, '&lt;');
// Аналогично для знака >
text = text.replace(/(?<=\s|[0-9])>/g, '&gt;');

// 4. Оставляем только разрешенные теги Телеграма
const allowedTags = "b|strong|i|em|u|s|strike|del|a|code|pre";
const sanitizeRegex = new RegExp(`<\/?(?!(?:${allowedTags})\\b)[a-z0-9]+[^>]*>`, 'gi');
text = text.replace(sanitizeRegex, '');

// 5. 🏗 АВТО-БАЛАНСИРОВЩИК ТЕГОВ (Лечит ошибку Unmatched end tag)
const stack =[];
const tagRegex = /<\/?([a-z]+)[^>]*>/gi;
let match;

// Проходим по всем тегам в тексте
while ((match = tagRegex.exec(text)) !== null) {
  const tag = match[1].toLowerCase();
  const isClosing = match[0].startsWith('</');

  if (!isClosing) {
    // Если тег открылся - кладем его в "память"
    stack.push(tag);
  } else {
    // Если тег закрылся - убираем его из памяти
    const lastIndex = stack.lastIndexOf(tag);
    if (lastIndex !== -1) {
      stack.splice(lastIndex, 1); 
    }
  }
}

// Все теги, которые остались в "памяти" - нейросеть забыла закрыть!
// Аккуратно закрываем их в самом конце текста в обратном порядке
for (let i = stack.length - 1; i >= 0; i--) {
  text += `</${stack[i]}>`;
}

// 6. Убираем лишние пустые строки
text = text.replace(/\n{3,}/g, '\n\n');

return { 
  json: { 
    ...$json,
    output: text.trim() 
  } 
};
